var n={en:`The startup wants split payouts and platform fees. Holding customer funds in-house may create legal and compliance obligations.`,ua:`Стартап хоче розділені виплати та комісію платформи. Самостійне зберігання коштів клієнтів може створити юридичні й регуляторні зобов’язання.`};var t={en:[`Compare managed marketplace payout, custom settlement and manual payout.`,`Draw trust, ledger and verification boundaries.`,`Write ADR covering reconciliation, compliance review and reversibility.`],ua:[`Порівняй керовані виплати, власний settlement і ручні виплати.`,`Намалюй межі довіри, журналу та перевірки.`,`Напиши ADR про звірення, правову оцінку й зворотність.`]};var i=[{en:`Payouts cannot be triggered by an unchecked client instruction.`,ua:`Виплата не запускається неперевіреною командою клієнта.`},{en:`External financial callbacks are authenticated and idempotent.`,ua:`Фінансові callback перевірені й ідемпотентні.`}];var c={scenario:n,tasks:t,checks:i};export{i as checks,c as default,n as scenario,t as tasks};